package pl.paweljarczak.cdafreeplayer;
import android.content.Context;import android.webkit.CookieManager;import android.webkit.WebSettings;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public final class CdaHttp {
    public static final class Result { public int status;public String body="";public boolean challenge; }
    private final Context context; public CdaHttp(Context c){context=c.getApplicationContext();}
    public String userAgent(){return WebSettings.getDefaultUserAgent(context);}
    public Result get(String url,RequestToken token)throws Exception{if(token!=null&&token.isCancelled())throw new InterruptedException();HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(true);c.setRequestProperty("User-Agent",userAgent());c.setRequestProperty("Accept","text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8");c.setRequestProperty("Accept-Language","pl-PL,pl;q=0.9,en;q=0.7");String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null&&!cookie.isEmpty())c.setRequestProperty("Cookie",cookie);int status=c.getResponseCode();InputStream in=status>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream();if(in!=null){byte[] buf=new byte[16384];int n;while((n=in.read(buf))>0){if(token!=null&&token.isCancelled()){c.disconnect();throw new InterruptedException();}b.write(buf,0,n);}in.close();}Result r=new Result();r.status=status;r.body=b.toString(StandardCharsets.UTF_8.name());String s=r.body.toLowerCase();r.challenge=status==403||status==429||status==503||s.contains("/cdn-cgi/challenge-platform/")||s.contains("cf-chl-")||s.contains("checking if you are not a bot")||s.contains("verify you are human")||s.contains("przeprowadzanie weryfikacji zabezpieczeń")||s.contains("just a moment...");c.disconnect();return r;}
}
